import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.BKVF-9lJ.js";const u=JSON.parse('{"title":"ADR 0002: operational Agent OS","description":"","frontmatter":{},"headers":[],"relativePath":"ai/decisions/0002-agent-operating-model.md","filePath":"ai/decisions/0002-agent-operating-model.md","lastUpdated":1790253757000}'),n={name:"ai/decisions/0002-agent-operating-model.md"};function r(s,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0002-operational-agent-os" tabindex="-1">ADR 0002: operational Agent OS <a class="header-anchor" href="#adr-0002-operational-agent-os" aria-label="Permalink to &quot;ADR 0002: operational Agent OS&quot;">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use one canonical repository contract with thin tool-specific adapters, invariant rules, and procedural skills. Skills must have explicit inputs, procedure, verification, and artifacts.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><p>Duplicated instructions drift. A layered contract lets Codex, Claude Code, and Antigravity share repository invariants while retaining small tool-specific habits. Explicit verification and handoff formats make autonomous work auditable.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>New workflows belong in <code>.agents/skills/</code>; durable architecture knowledge belongs in <code>docs/ai/decisions/</code>. Adapters should link to the canonical contract rather than copy it.</p>',7)])])}const f=a(n,[["render",r]]);export{u as __pageData,f as default};
